link.script:
(function(){
  var loaded = false;
  function loadGTM(){
    if (loaded) return; loaded = true;
    (function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':
    new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],
    j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src=
    '//sio2.ctox.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);
    })(window,document,'script','dataLayer','GTM-TGRXM9MJ');
    ['pointerdown','scroll','keydown','touchstart','mousemove'].forEach(function(e){
      window.removeEventListener(e, loadGTM, {passive:true});
    });
  }
  ['pointerdown','scroll','keydown','touchstart','mousemove'].forEach(function(e){
    window.addEventListener(e, loadGTM, {passive:true, once:true});
  });
  setTimeout(loadGTM, 5000);
})();

body.script:
  // Testimonials — content doubled for seamless marquee
  const TESTIMONIALS = [
    ["Paul McRae", "CEO, TransformativeHLTH", "avatar-paul-mcrae-104.webp", "\u201cThe KPI-driven framework became a real hook in my sales conversations. Once I started framing things that way, it changed how I approached clients and helped me stand out.\u201d"],
    ["Chris Marrs", "President, ChrisMarrsCTO", "avatar-chris-104.webp", "\u201cThe KPI-driven framework became a real hook in my sales conversations. Once I started framing things that way, it changed how I approached clients and helped me stand out.\u201d"],
    ["Brian Dedischew", "Fractional CTO | TodayCTO", "avatar-brian-104.webp", "\u201cYou\u2019ve completely changed my paradigm. I was looking at this all wrong\u2026 This is exactly what I needed to get back on track. You completely shifted my mindset. I wish I had done this a month ago.\u201d"],
    ["Paul Benson", "Founder, MRPABENSON IT", "avatar-paul-benson-104.webp", "\u201cWorking with CTOx has been one of the most transformative and strategically valuable collaborations I\u2019ve experienced. Simply put, CTOx vastly exceeded expectations.\u201d"],
    ["David Shake", "CTO | Fusion Solutions Group", "avatar-david-104.webp", "\u201cI\u2019ve been in C-level roles for years. But this (CTOx Accelerator) is exactly what I needed to succeed as a fractional CTO. The resources, the people, the tools\u2014it\u2019s been invaluable.\u201d"],
    ["Gav M.", "Tech Startups/Multiple Exits", "avatar-gav-104.webp", "\u201cCTOx helped me build a $500K+ consulting business in months\u2014and I\u2019m just getting started. I actually took my website down because I was getting too many leads. That\u2019s how well it\u2019s working.\u201d"],
    ["Tony Winter", "Fractional CTO", "avatar-tony-104.webp", "\u201cCTOx Accelerator was one of the best choices I could have made. Without it, I\u2019d be stuck in months of trial and error trying to launch my fractional practice. It\u2019s all been invaluable.\u201d"],
    ["Keith Piccininno", "Fractional CTO", "avatar-keith-104.webp", "\u201cThe best part of CTOx Accelerator is the community and the tools. You\u2019re not just networking, you\u2019re accelerating. They give you a real head start in building whatever you need next.\u201d"]
  ];
  const cardHTML = ([name, role, avatar, quote]) => `







${name}
${role}


★★★★★
      ${quote}
    `;
  document.getElementById("marquee").innerHTML =
    TESTIMONIALS.map(cardHTML).join("") + TESTIMONIALS.map(cardHTML).join("");

  // Brand logos — content doubled for seamless marquee
  const BRANDS = [
    ["logo-apple.svg", "Apple", "lg"],
    ["logo-intuit.svg", "Intuit", ""],
    ["logo-uber.svg", "Uber", ""],
    ["logo-cisco.svg", "Cisco", ""],
    ["logo-aramark.svg", "Aramark", ""],
    ["logo-southwest.svg", "Southwest", ""],
    ["logo-northrop.svg", "Northrop Grumman", ""],
    ["logo-verizon.svg", "Verizon", ""],
    ["logo-accenture.svg", "Accenture", ""],
    ["logo-caterpillar.svg", "Caterpillar", ""],
    ["logo-honeywell.svg", "Honeywell", ""]
  ];
  const logoHTML = ([file, name, cls]) =>
    `
`;
  const logosStrip = BRANDS.map(logoHTML).join("") + BRANDS.map(logoHTML).join("");
  document.getElementById("brandsRow").innerHTML = logosStrip;

  // iOS Safari snapshots accelerated keyframe transforms when the animation
  // first starts — at that point these rows are empty (width 0), so the
  // translateX(-50%) resolves to 0px and the marquee never moves. Restart
  // the animations now that the rows have their real width.
  requestAnimationFrame(() => {
    // Batch: one style write pass, ONE forced reflow, one restore pass
    // (two separate offsetWidth reads showed up as 56ms forced reflow in PSI).
    const els = ["brandsRow", "marquee"].map(id => document.getElementById(id)).filter(Boolean);
    els.forEach(el => { el.style.animation = "none"; });
    if (els[0]) void els[0].offsetWidth;
    els.forEach(el => { el.style.animation = ""; });
  });

  // Fractional 101 — player + playlist (video IDs from fractional-cto-101)
  const EPISODES = [
    { n: "01", title: "What is a Fractional CTO",
      desc: "The role, the model, and why companies pay for part-time technical leadership.",
      cover: "assets-v2/video-1-what-is-it-726.webp", ytid: "tYQAGlgJqvA" },
    { n: "02", title: "How to know if you’re qualified",
      desc: "The real bar for going fractional, and why you likely already clear it.",
      cover: "assets-v2/video-2-qualified-726.webp", ytid: "QsbQ-Ws86rQ" },
    { n: "03", title: "How to find clients",
      desc: "Where the first engagements come from, and the outreach that fills a pipeline.",
      cover: "assets-v2/video-3-clients-726.webp", ytid: "KWq7Pqe6P6I" },
    { n: "04", title: "What is a day in the life",
      desc: "What the work really looks like week to week once you’re running a fractional practice.",
      cover: "assets-v2/video-4-becoming-726.webp", ytid: "3yy8AKf_4-A" },
    { n: "05", title: "Not a salesperson? No worries.",
      desc: "How to land clients without selling, and why the best fractional CTOs rarely pitch.",
      cover: "assets-v2/video-5-sales-726.webp", ytid: "pKJgM2lgGzk" }
  ];
  const epButtons = document.querySelectorAll(".ep");
  function selectEpisode(i) {
    const e = EPISODES[i];
    epButtons.forEach((el, idx) => {
      el.classList.toggle("active", idx === i);
      el.classList.toggle("done", idx < i);
      el.querySelector(".ep-body span").textContent =
        idx === i ? "Now playing" : (idx < i ? "Watched" : "Part " + EPISODES[idx].n);
    });
    const pct = Math.round(((i + 1) / EPISODES.length) * 100);
    document.getElementById("progress-bar").style.width = pct + "%";
    document.getElementById("progress-label").textContent = "Part " + (i + 1) + " of " + EPISODES.length;
    document.getElementById("progress-pct").textContent = pct + "%";
    const player = document.getElementById("player");
    player.innerHTML =
      '' +
        '' +
        '' +
          '' +
        '' +
      '';
    player.querySelector(".cover-link").addEventListener("click", () => playInline(e.ytid));
  }
  function playInline(id) {
    // YouTube rejects referrer-less embeds (Error 153) — from a local file://
    // preview, open the video on YouTube instead of a dead iframe.
    if (location.protocol === "file:") {
      window.open("https://www.youtube.com/watch?v=" + id, "_blank", "noopener");
      return;
    }
    document.getElementById("player").innerHTML =
      '';
  }
  epButtons.forEach(el => el.addEventListener("click", () => selectEpisode(parseInt(el.dataset.i, 10))));
  selectEpisode(0);

  // Orange glow trails the cursor (mouse pointers only; touch stays glow-free)
  (function () {
    const glow = document.getElementById("cursorGlow");
    if (!glow || !window.matchMedia("(pointer: fine)").matches) return;
    const snap = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let tx = innerWidth / 2, ty = innerHeight / 3, x = tx, y = ty, shown = false;
    addEventListener("mousemove", e => {
      tx = e.clientX; ty = e.clientY;
      if (!shown) { shown = true; x = tx; y = ty; glow.style.opacity = "1"; }
    });
    document.documentElement.addEventListener("mouseleave", () => { glow.style.opacity = "0"; shown = false; });
    (function tick() {
      var dx = tx - x, dy = ty - y;
      // only write styles while the glow is still catching up — constant
      // style writes under the pointer suppress custom CSS cursors in Chrome
      if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5) {
        x += dx * (snap ? 1 : 0.08);
        y += dy * (snap ? 1 : 0.08);
        glow.style.transform = "translate3d(" + x + "px," + y + "px,0)";
      }
      requestAnimationFrame(tick);
    })();
  })();

  // Video testimonials — all of them (data mirrors testimonials.html)
  const VT_ALL = [
  ["Sanjay Akut","h3RwXdzQYRg","The \u2018Engage, Advisor, Workshop\u2019 offerings were humongous because that\u2019s literally the core of my business at this point."],
  ["George Reyna","zSHgvs37exc","CTOx gave me the space to show up authentically and make a real impact in others\u2019 businesses\u2014and that\u2019s been incredibly rewarding."],
  ["Amit Moravchick","T3JMYyNFmys","I\u2019ve found my destiny. Being a fCTO finally feels like the right fit. The freedom to live fully. The clarity on where I bring value. It all makes sense now."],
  ["Christopher Grant","AmbYdVCFFQU","The meetings are engaging, the content is diverse, and I genuinely enjoy connecting with the people on calls and in Slack. Makes a big difference."],
  ["Christian Wiles","9fDHdf7BlBk","The relationships, the tech-forward mindset, the peer group calls. CTOx creates the environment where you\u2019re constantly learning and building."],
  ["Jon Freedman","5Acqr7vgYKg","CTOx did exactly what it promised\u2014it accelerated my business setup. The ROI was clear, and the feedback from real humans made all the difference."],
  ["Todd Deshane","i1S0qqOn-EM","CTOx gave me the clarity I couldn\u2019t find on my own. The community, the coaching, the accountability\u2014it pushed me to commit, act, and win early."],
  ["Gav M.","U-AI9QysyWk","I was blown away by the content and the sessions. It\u2019s great to be part of a community like this. I\u2019m a very happy customer."],
  ["Shubham Sethi","SSUE0wa53Oc","Landing that first client changed everything. I went from anxious to confident, from uncertain to building momentum. Now I know I can scale."],
  ["Dawn Fitzgerald","a9zh06udCj0","Fractional CTO is a richer, long-term way to support growing companies. CTOx gave me the training and a community of peers to grow alongside."],
  ["Michael Virnoche","kjdJTMI7C14","The biggest benefit I got out of CTOx really comes down to the community. Having access to so much experience is what truly pays dividends when working with clients."],
  ["Taylor Johnson","6coueSooXWY","There\u2019s no fluff. It\u2019s just very direct, very real. I\u2019m like, this is incredibly valuable. One of my buddies is a CRO, and he\u2019s heard of you guys and he\u2019s like, \u2018Oh, they do great work!\u2019"],
  ["Tony Winter","Ui1lzX1Nurw","CTOx Accelerator was one of the best choices I could have made. Without it, I\u2019d be stuck in months of trial and error trying to launch my fractional practice. It\u2019s all been invaluable."],
  ["David Brumbaugh","it3bonk1W4M","CTOx isn\u2019t just coaching \u2014 it\u2019s an incredible mix of great people, powerful peer groups, and more resources than I can count. I love it. Glad to be part of it."],
  ["Ravi Sandhu","8ZB4mVkksS4","A lot of the stuff you teach at CTOx matched the way I already thought \u2014 but you gave it words and legitimacy. It matched my skills more than just doing consultancy."],
  ["Vinay Venkataraghavan","ljtTHIr4Zkw","The clarity and the way you\u2019re framing everything is incredible. You\u2019re amazing at what you do."],
  ["Bob Stewart","CkkdFXbyIZY","I saw CTOx Accelerator as more than just a peer network. It\u2019s a signal amplifier for those of us stewarding the future of intelligence\u2014where leverage comes not just from tech, but execution."],
  ["Yeomy Waller","MbMdj-4KysQ","By asking, you\u2019re not bothering people\u2014you\u2019re giving them the opportunity to help. That\u2019s priceless for them, too. Network activation changed everything. Just stick with the program\u2014it works."],
  ["Keith Piccininno","vLpqeTgXdQc","The best part of CTOx Accelerator is the community and the tools. You\u2019re not just networking\u2014you\u2019re accelerating. They give you a real head start in building whatever you need next."],
  ["Michael Kofman","_Jo8JW1fWlI","I had low expectations, but CTOx became everything I didn\u2019t know I needed. It\u2019s not just strategy\u2014it\u2019s the people, the support, and the push I needed to finally succeed."],
  ["Asim Mohammad","hxGBORlVjos","CTOx is an enabling tool. The only way to stay ahead in tech is by surrounding yourself with smart, capable people\u2014and CTOx offers exactly that kind of forward-thinking community."],
  ["Paul McRae","IjyrkcfjMZU","This program gave me the mindset shift I didn\u2019t know I needed. It\u2019s not just about business growth\u2014it\u2019s about rewiring how you think, evaluate opportunity, and reclaim your time and purpose."],
  ["Jacob Silberstein","LmeXCAwgblg","Just as I was ready to give up, CTOx pulled me back in. That one check-in unlocked the opportunity I needed\u2014and helped me step into a stronger version of myself."],
  ["John Fitzpatrick","XT8Fk8EJaQY","The CTOx Accelerator is great for framing how to think independently\u2014while also giving you access to a brilliant peer network where ideas, platforms, and tools are shared generously."],
  ["Jon Benedict","yo5ui8SpZRc","Before the CTOx Accelerator, I was lost trying to market myself. Now, I\u2019m a confident entrepreneur with a clear message, a repeatable system, and zero hesitation about showing up as myself."],
  ["Paul Benson","Fr3l1gA_3mU","CTOx challenged decades of W2 thinking. I didn\u2019t just learn new tactics\u2014I learned how to think like a founder. Now I choose who I work with and why. That changed everything."],
  ["Glenn Antoine","yoX-IwvZU-w","CTOx helped me escape the repetition of W2 life. As a fractional leader, I solve diverse challenges across companies\u2014learning, growing, and delivering impact far beyond any one seat. That\u2019s freedom."],
  ["David Shake","fjILuW6mnRk","CTOx is literally the accelerator\u2014it gave me a four- to five-year head start over where I would have been without it. I wouldn\u2019t be where I am today without CTOx; it\u2019s truly been a lifesaver."],
  ["Prashanthi Nuthi","TCxTElu6Ars","Before CTOx I was skeptical and kept asking people for roles because I couldn\u2019t explain my value. A month later I\u2019m finally clear about my skills, and opportunities started coming my way."]
];
  document.getElementById("vtGrid").innerHTML = VT_ALL.slice(0, 27).map(([n, id, q]) => `









        “${q}”

${n}

    `).join("");
  document.querySelectorAll(".vt-thumb").forEach(t => t.addEventListener("click", () => {
    const id = t.dataset.id;
    if (location.protocol === "file:") { window.open("https://www.youtube.com/watch?v=" + id, "_blank", "noopener"); return; }
    t.innerHTML = '';
    t.style.cursor = "default";
  }));

  // Close mobile nav when a link is tapped
  document.querySelectorAll("#nav a").forEach(a => a.addEventListener("click", () => {
    document.querySelector(".header").classList.remove("menu-open");
    document.getElementById("nav").classList.remove("open");
  }));
